11	type ObsidianConnectorState =
12	    | 'initializing'
13	    | 'connected'
14	    | 'offline'
15	    | 'cert_untrusted'
16	    | 'missing_api_key';
17	
18	type ConnectorFailure = {
19	    code: string | null;
20	    message: string;
21	    state: Exclude<ObsidianConnectorState, 'connected' | 'initializing'>;
22	    url: string;
23	};
