36	
37	const TLS_ERROR_CODES = new Set([
38	    'DEPTH_ZERO_SELF_SIGNED_CERT',
39	    'SELF_SIGNED_CERT_IN_CHAIN',
40	    'UNABLE_TO_VERIFY_LEAF_SIGNATURE',
41	    'CERT_HAS_EXPIRED',
42	    'ERR_TLS_CERT_ALTNAME_INVALID'
43	]);
44	
45	function splitPemCertificates(content: string): string[] {
46	    const matches = content.match(/-----BEGIN CERTIFICATE-----[\s\S]+?-----END CERTIFICATE-----/g);
47	    return matches ? matches.map((entry) => entry.trim()).filter(Boolean) : [];
48	}
49	
50	function dedupeCertificates(certificates: string[]): string[] {
51	    return [...new Set(certificates.map((entry) => entry.trim()).filter(Boolean))];
52	}
