65	    private reconnectAttempts: number = 0;
66	    private state: ObsidianConnectorState = 'initializing';
67	    private lastErrorCode: string | null = null;
68	    private lastErrorMessage: string | null = null;
69	    private lastFailureUrl: string | null = null;
70	    private lastFailureAt: string | null = null;
71	    private readonly cacheTtl = 15000;
72	    private readonly allowInsecureTls = process.env.OBSIDIAN_REST_ALLOW_INSECURE_TLS === 'true';
73	    private readonly explicitCaBundlePath = (process.env.OBSIDIAN_REST_CA_BUNDLE_PATH || process.env.OBSIDIAN_REST_CA_FILE || '').trim();
74	    private readonly caBundlePath: string | null;
