79	    constructor() {
80	        this.apiKey = process.env.OBSIDIAN_REST_API_KEY || '';
81	        const port = process.env.OBSIDIAN_REST_API_PORT || '27124';
82	        this.baseUrl = `https://127.0.0.1:${port}`;
83	        this.workspaceCandidatePaths = [
84	            SystemConfig.resolve('.obsidian/workspace.json'),
85	            SystemConfig.resolve('06_NETWORK-SYNC/C2MOVIEZ/Database/.obsidian/workspace.json')
86	        ];
87	
88	        const trustConfig = this.resolveTrustConfiguration(port);
89	        this.trustedCaCertificates = trustConfig.certificates;
90	        this.caBundlePath = trustConfig.bundlePath;
91	        this.trustSource = trustConfig.source;
92	        
93	        // Initial placeholder client
94	        this.client = this.buildClient(this.baseUrl, 2000);
95	
96	        if (!this.apiKey) {
97	            this.state = 'missing_api_key';
98	            console.warn('⬡ OBSIDIAN_REST_API_KEY is missing in .env');
99	        } else {
100	            void this.initClient().then(success => {
101	                if (!success) {
102	                    console.warn('⬡ OBSIDIAN_REST_API :: Exhausted all protocols. Still offline.');
103	                }
104	            });
105	        }
106	
107	        if (this.allowInsecureTls) {
108	            console.warn('⬡ OBSIDIAN_REST_API :: Insecure TLS validation enabled for local development.');
109	        } else if (this.trustSource !== 'default') {
110	            console.log(`⬡ OBSIDIAN_REST_API :: Trust source ${this.trustSource}${this.caBundlePath ? ` (${this.caBundlePath})` : ''}`);
111	        }
