114	    private buildClient(url: string, timeout: number): AxiosInstance {
115	        const httpsOptions: https.AgentOptions = {
116	            rejectUnauthorized: !this.allowInsecureTls
117	        };
118	
119	        if (!this.allowInsecureTls && this.trustedCaCertificates && this.trustedCaCertificates.length > 0) {
120	            httpsOptions.ca = this.trustedCaCertificates;
121	        }
122	
123	        return axios.create({
124	            baseURL: url,
125	            timeout,
126	            headers: {
127	                'Authorization': `Bearer ${this.apiKey}`,
128	                'Content-Type': 'application/json'
129	            },
130	            httpsAgent: new https.Agent(httpsOptions)
131	        });
132	    }
