134	    private resolveTrustConfiguration(port: string) {
135	        const defaultCertificates = Array.isArray(tls.rootCertificates) ? tls.rootCertificates : [];
136	        const systemCertificates = typeof tls.getCACertificates === 'function'
137	            ? tls.getCACertificates('system')
138	            : [];
139	
140	        const pluginCertificate = this.extractPluginCertificate(port);
141	
142	        let bundlePath: string | null = null;
143	        let source = systemCertificates.length > 0 ? 'default+system' : 'default';
144	        const certificates = [...defaultCertificates, ...systemCertificates];
145	
146	        if (this.explicitCaBundlePath) {
147	            const fileCertificates = this.readCertificateFile(this.explicitCaBundlePath);
148	            if (fileCertificates.length > 0) {
149	                bundlePath = this.explicitCaBundlePath;
150	                source = systemCertificates.length > 0 ? 'bundle+default+system' : 'bundle+default';
151	                certificates.push(...fileCertificates);
152	            } else {
153	                console.warn(`⬡ OBSIDIAN_REST_API :: Configured CA bundle not found or invalid at ${this.explicitCaBundlePath}`);
154	            }
155	        } else if (pluginCertificate) {
156	            bundlePath = pluginCertificate.sourcePath;
157	            source = systemCertificates.length > 0 ? 'plugin-data+default+system' : 'plugin-data+default';
158	            certificates.push(pluginCertificate.cert);
159	        }
160	
161	        const deduped = dedupeCertificates(certificates);
162	        return {
163	            certificates: deduped.length > 0 ? deduped : null,
164	            bundlePath,
165	            source
166	        };
167	    }
