169	    private readCertificateFile(filePath: string): string[] {
170	        try {
171	            if (!fs.existsSync(filePath)) return [];
172	            const content = fs.readFileSync(filePath, 'utf8');
173	            return splitPemCertificates(content);
174	        } catch {
175	            return [];
176	        }
177	    }
