179	    private extractPluginCertificate(port: string) {
180	        const candidatePaths = [
181	            SystemConfig.resolve('.obsidian/plugins/obsidian-local-rest-api/data.json'),
182	            SystemConfig.resolve('06_NETWORK-SYNC/C2MOVIEZ/Database/.obsidian/plugins/obsidian-local-rest-api/data.json')
183	        ];
184	
185	        for (const candidatePath of candidatePaths) {
186	            try {
187	                if (!fs.existsSync(candidatePath)) continue;
188	
189	                const raw = JSON.parse(fs.readFileSync(candidatePath, 'utf8')) as {
190	                    port?: number;
191	                    apiKey?: string;
192	                    crypto?: { cert?: string };
193	                };
194	
195	                const portMatches = String(raw.port || '') === String(port);
196	                const keyMatches = Boolean(raw.apiKey && this.apiKey && raw.apiKey === this.apiKey);
197	                const cert = raw.crypto?.cert?.trim();
198	
199	                if (!cert || (!portMatches && !keyMatches)) continue;
200	
201	                return {
202	                    cert,
203	                    sourcePath: candidatePath
204	                };
205	            } catch {
206	                // Ignore malformed plugin config and continue discovery.
207	            }
208	        }
209	
210	        return null;
211	    }
