213	    private readJsonFile<T>(filePath: string): T | null {
214	        try {
215	            if (!fs.existsSync(filePath)) return null;
216	            const raw = fs.readFileSync(filePath, 'utf8');
217	            return JSON.parse(raw) as T;
218	        } catch {
219	            return null;
220	        }
221	    }
