223	    private loadWorkspaceSnapshot(): ObsidianWorkspaceSnapshot | null {
224	        for (const candidatePath of this.workspaceCandidatePaths) {
225	            const snapshot = this.readJsonFile<ObsidianWorkspaceSnapshot>(candidatePath);
226	            if (snapshot) return snapshot;
227	        }
228	        return null;
229	    }
