231	    private findWorkspaceFileById(node: unknown, targetId: string): string | null {
232	        if (!node || typeof node !== 'object') return null;
233	
234	        if (Array.isArray(node)) {
235	            for (const entry of node) {
236	                const match = this.findWorkspaceFileById(entry, targetId);
237	                if (match) return match;
238	            }
239	            return null;
240	        }
241	
242	        const record = node as Record<string, unknown>;
243	        if (record.id === targetId) {
244	            const state = record.state as Record<string, unknown> | undefined;
245	            const nestedState = state?.state as Record<string, unknown> | undefined;
246	            const file = nestedState?.file;
247	            if (typeof file === 'string' && file.trim()) {
248	                return file.trim().replace(/\\/g, '/');
249	            }
250	        }
251	
252	        for (const value of Object.values(record)) {
253	            const match = this.findWorkspaceFileById(value, targetId);
254	            if (match) return match;
255	        }
256	
257	        return null;
258	    }
