260	    private resolveWorkspaceActiveFile(): ActiveFileDescriptor | null {
261	        const snapshot = this.loadWorkspaceSnapshot();
262	        if (!snapshot) return null;
263	
264	        const activeId = typeof snapshot.active === 'string' ? snapshot.active : '';
265	        if (activeId) {
266	            const activePath = this.findWorkspaceFileById(snapshot.main, activeId);
267	            if (activePath) {
268	                return {
269	                    path: activePath,
270	                    mode: 'file',
271	                    source: 'workspace_active'
272	                };
273	            }
274	        }
275	
276	        if (Array.isArray(snapshot.lastOpenFiles)) {
277	            for (const candidate of snapshot.lastOpenFiles) {
278	                if (typeof candidate !== 'string') continue;
279	                const normalized = candidate.trim().replace(/\\/g, '/');
280	                if (normalized.endsWith('.md')) {
281	                    return {
282	                        path: normalized,
283	                        mode: 'file',
284	                        source: 'workspace_recent'
285	                    };
286	                }
287	            }
288	        }
289	
290	        return null;
291	    }
