293	    private async resolveRestActiveFile(): Promise<ActiveFileDescriptor | null> {
294	        try {
295	            const response = await this.client.get('/active/');
296	            const data = response.data as { path?: string };
297	            if (typeof data?.path === 'string' && data.path.trim()) {
298	                return {
299	                    path: data.path.trim().replace(/\\/g, '/'),
300	                    mode: 'rest',
301	                    source: 'rest'
302	                };
303	            }
304	        } catch {
305	            // Fall through to file-backed workspace recovery.
306	        }
307	
308	        return this.resolveWorkspaceActiveFile();
309	    }
