311	    private normalizeFailure(error: any, url: string): ConnectorFailure {
312	        const code = typeof error?.code === 'string' ? error.code : null;
313	        const message = typeof error?.message === 'string' ? error.message : 'UNKNOWN_OBSIDIAN_ERROR';
314	        const lowerMessage = message.toLowerCase();
315	        const isTlsTrustError = TLS_ERROR_CODES.has(code || '')
316	            || lowerMessage.includes('self-signed certificate')
317	            || lowerMessage.includes('unable to verify')
318	            || lowerMessage.includes('certificate');
319	
320	        if (!this.apiKey) {
321	            return {
322	                code,
323	                message,
324	                state: 'missing_api_key',
325	                url
326	            };
327	        }
328	
329	        return {
330	            code,
331	            message,
332	            state: isTlsTrustError ? 'cert_untrusted' : 'offline',
333	            url
334	        };
335	    }
336	
337	    private applyFailure(failure: ConnectorFailure) {
338	        this.isConnected = false;
339	        this.state = failure.state;
340	        this.lastErrorCode = failure.code;
341	        this.lastErrorMessage = failure.message;
342	        this.lastFailureUrl = failure.url;
343	        this.lastFailureAt = new Date().toISOString();
344	    }
