346	    private markConnected(url: string) {
347	        this.baseUrl = url;
348	        this.isConnected = true;
349	        this.state = 'connected';
350	        this.lastErrorCode = null;
351	        this.lastErrorMessage = null;
352	        this.lastFailureUrl = null;
353	        this.lastFailureAt = null;
354	        this.reconnectAttempts = 0;
355	    }
