357	    private async initClient() {
358	        if (!this.apiKey) {
359	            this.state = 'missing_api_key';
360	            return false;
361	        }
362	
363	        const ports = [process.env.OBSIDIAN_REST_API_PORT || '27124', '27123'];
364	        const protocols = ['https', 'http'];
365	        let trustFailure: ConnectorFailure | null = null;
366	        let lastFailure: ConnectorFailure | null = null;
367	        
368	        for (const port of ports) {
369	            for (const protocol of protocols) {
370	                const url = `${protocol}://127.0.0.1:${port}`;
371	                const testClient = this.buildClient(url, 2000);
372	
373	                try {
374	                    await testClient.get('/');
375	                    this.client = testClient;
376	                    this.markConnected(url);
377	                    console.log(`⬡ OBSIDIAN_CONNECTOR :: Bound to ${url}`);
378	                    return true;
379	                } catch (error) {
380	                    const failure = this.normalizeFailure(error, url);
381	                    lastFailure = failure;
382	                    if (failure.state === 'cert_untrusted' && !trustFailure) {
383	                        trustFailure = failure;
384	                    }
385	                }
386	            }
387	        }
388	
389	        if (trustFailure) {
390	            this.applyFailure(trustFailure);
391	        } else if (lastFailure) {
392	            this.applyFailure(lastFailure);
393	        }
394	
395	        return false;
396	    }
