402	    public async reconnectWithBackoff(maxAttempts: number = 5, initialDelayMs: number = 1000): Promise<boolean> {
403	        for (let attempt = 1; attempt <= maxAttempts; attempt++) {
404	            this.reconnectAttempts = attempt;
405	            if (await this.initClient()) {
406	                return true;
407	            }
408	
409	            const backoffMs = initialDelayMs * Math.pow(2, attempt - 1);
410	            console.warn(`⬡ OBSIDIAN_RECONNECT :: Attempt ${attempt}/${maxAttempts} failed, retrying in ${backoffMs}ms`);
411	            await new Promise((resolve) => setTimeout(resolve, backoffMs));
412	        }
413	
414	        return false;
415	    }
