419	        const mode = this.isConnected ? 'rest' : (workspaceActiveFile ? 'file' : 'offline');
420	        return {
421	            state: this.state,
422	            connected: this.isConnected,
423	            mode,
424	            baseUrl: this.baseUrl,
425	            reconnectAttempts: this.reconnectAttempts,
426	            allowInsecureTls: this.allowInsecureTls,
427	            trustSource: this.trustSource,
428	            caBundlePath: this.caBundlePath,
429	            lastErrorCode: this.lastErrorCode,
430	            lastErrorMessage: this.lastErrorMessage,
431	            lastFailureUrl: this.lastFailureUrl,
432	            lastFailureAt: this.lastFailureAt,
433	            apiKeyConfigured: Boolean(this.apiKey),
434	            workspaceFallbackAvailable: Boolean(workspaceActiveFile),
435	            workspaceActiveFile: workspaceActiveFile?.path || null
436	        };
