439	    /**
440	     * Check if the API is reachable with sliding cache to prevent flickering
441	     */
442	    async ping(): Promise<boolean> {
443	        const now = Date.now();
444	        if (this.isConnected && (now - this.lastPingTime < this.cacheTtl)) {
445	            return true;
446	        }
447	
448	        try {
449	            await this.client.get('/', { timeout: 2000 });
450	            this.isConnected = true;
451	            this.state = 'connected';
452	            this.lastPingTime = now;
453	            this.lastErrorCode = null;
454	            this.lastErrorMessage = null;
455	            this.lastFailureUrl = null;
456	            this.lastFailureAt = null;
457	            return true;
458	        } catch (error) {
459	            const failure = this.normalizeFailure(error, this.baseUrl);
460	            this.applyFailure(failure);
461	            if (!this.resolveWorkspaceActiveFile()) {
462	                console.error(`⬡ OBSIDIAN_REST_${failure.state.toUpperCase()} [${this.baseUrl}] ::`, failure.message);
463	            }
464	            return false;
465	        }
466	    }
