7	function isWithinRoot(root: string, candidate: string): boolean {
8	    const relative = path.relative(root, candidate);
9	    return relative === '' || (!relative.startsWith('..') && !path.isAbsolute(relative));
10	}
11	
12	function locateRepoRoot(): string {
13	    const envRoot = process.env.NUDIMMUD_ROOT || process.env.SYSTEM_ROOT;
14	    if (envRoot) {
15	        const resolvedEnvRoot = path.resolve(envRoot);
16	        console.log(`⬡ SYSTEM_CONFIG :: REPO_ROOT_RESOLVED (via ENV): \${resolvedEnvRoot}`);
17	        return resolvedEnvRoot;
18	    }
19	
20	    const anchors = [process.cwd(), __dirname];
21	    for (const anchor of anchors) {
22	        let current = path.resolve(anchor);
23	        while (true) {
24	            if (
25	                fs.existsSync(path.join(current, 'backend', 'package.json')) &&
26	                fs.existsSync(path.join(current, '_SYSTEM'))
27	            ) {
28	                return current;
29	            }
30	
31	            const parent = path.dirname(current);
32	            if (parent === current) break;
33	            current = parent;
34	        }
35	    }
36	
37	    const finalRoot = path.resolve(process.cwd());
38	    console.log(`⬡ SYSTEM_CONFIG :: REPO_ROOT_RESOLVED: \${finalRoot}`);
39	    return finalRoot;
40	}
