47	    // Determine the current root based on environment or execution path
48	    ROOT: locateRepoRoot(),
49	    
50	    // Ecosystem A: System Assets
51	    SYSTEM: {
52	        BACKEND: 'backend',
53	        DATA: 'backend/data',
54	        LOGS: 'backend/data/logs',
55	        DB: 'backend/data/nudimmud.db'
56	    },
57	
58	    // Ecosystem B: Knowledge Vaults (Obsidian)
59	    VAULTS: {
