61	        CLAUDIO: '06_NETWORK-SYNC/C2MOVIEZ',
62	        STRUCTURE: {
63	            COSMOLOGY: '06_KNOWLEDGE-BASE/01_COSMOLOGY',
64	            OPERATIONAL: '06_KNOWLEDGE-BASE/05_OPERATIONAL',
65	            RESEARCH: 'RESEARCH'
66	        }
67	    },
68	
69	    /**
70	     * Resolve a relative path to the current system root
71	     */
72	    resolve(subPath: string): string {
73	        const resolved = path.isAbsolute(subPath)
74	            ? path.resolve(subPath)
75	            : path.resolve(this.ROOT, subPath);
76	
77	        console.log('⬡ SYSTEM_CONFIG :: RESOLVE:', subPath, '->', resolved, '(ROOT:', this.ROOT, ')');
78	
79	        if (!isWithinRoot(this.ROOT, resolved)) {
80	            throw new Error(`ACCESS_DENIED: ${subPath} (resolved: ${resolved}, root: ${this.ROOT})`);
81	        }
82	
83	        return resolved;
84	    },
85	
86	    /**
87	     * Diagnostic: Check if we are in "SSD_MODE" or "LOCAL_MODE"
88	     */
89	    getMode(): 'SSD' | 'LOCAL' {
90	        return this.ROOT.startsWith('/Volumes/') ? 'SSD' : 'LOCAL';
91	    }
92	};
