3	export const ORACLE_COMMAND_ENDPOINT = '/api/oracle/command';
4	export const ORACLE_COMMAND_BUDGETS_MS = {
5	    deliberationDelay: 150,
6	    staleSoft: 30_000,
7	    staleHard: 60_000,
8	    directHardTimeout: 120_000,
9	    councilHardTimeout: 180_000
10	} as const;
11	
12	export type OracleCommandPhase =
13	    | 'idle'
14	    | 'submitted'
15	    | 'deliberating'
16	    | 'stale'
17	    | 'completed'
18	    | 'failed';
19	
20	export type OracleCommandSource = 'typed' | 'voice';
21	export type OracleCommandMode = 'direct' | 'council';
22	export type OracleStaleLevel = 'soft' | 'hard';
23	
24	export interface OracleCommandResponse {
25	    [key: string]: any;
26	}
27	
28	export interface OracleCommandState {
29	    requestId: string | null;
30	    source: OracleCommandSource | null;
31	    mode: OracleCommandMode;
32	    phase: OracleCommandPhase;
33	    staleLevel: OracleStaleLevel | null;
34	    command: string;
35	    response: OracleCommandResponse | null;
36	    error: string | null;
37	    submittedAt: number | null;
38	    settledAt: number | null;
39	    elapsedMs: number;
40	}
41	
42	export interface OracleSubmitOptions {
43	    command: string;
44	    source?: OracleCommandSource;
45	    useCouncil?: boolean;
46	    modelId?: string;
47	    signal?: AbortSignal;
48	}
49	
50	type OracleCommandListener = (state: OracleCommandState) => void;
51	
52	const listeners = new Set<OracleCommandListener>();
53	
54	let state: OracleCommandState = createIdleState();
55	let requestCounter = 0;
56	let activeController: AbortController | null = null;
57	let phaseTimer: number | null = null;
58	let staleSoftTimer: number | null = null;
59	let staleHardTimer: number | null = null;
60	let tickInterval: number | null = null;
61	
62	function createIdleState(): OracleCommandState {
63	    return {
64	        requestId: null,
65	        source: null,
66	        mode: 'direct',
67	        phase: 'idle',
68	        staleLevel: null,
69	        command: '',
70	        response: null,
71	        error: null,
72	        submittedAt: null,
73	        settledAt: null,
74	        elapsedMs: 0
75	    };
76	}
77	
78	function cloneState(current: OracleCommandState): OracleCommandState {
79	    return {
80	        ...current,
81	        response: current.response ? { ...current.response } : null
82	    };
83	}
84	
85	function emit() {
86	    const snapshot = cloneState(state);
87	    listeners.forEach((listener) => listener(snapshot));
88	}
89	
90	function setState(nextState: OracleCommandState | ((current: OracleCommandState) => OracleCommandState)) {
91	    state = typeof nextState === 'function' ? nextState(state) : nextState;
92	    emit();
93	}
94	
95	function clearTimeoutSafe(timer: number | null) {
96	    if (timer !== null) {
97	        globalThis.clearTimeout(timer);
98	    }
99	}
100	
101	function clearIntervalSafe(timer: number | null) {
102	    if (timer !== null) {
103	        globalThis.clearInterval(timer);
104	    }
105	}
106	
107	function stopTimers() {
108	    clearTimeoutSafe(phaseTimer);
109	    clearTimeoutSafe(staleSoftTimer);
110	    clearTimeoutSafe(staleHardTimer);
111	    clearIntervalSafe(tickInterval);
112	    phaseTimer = null;
113	    staleSoftTimer = null;
114	    staleHardTimer = null;
115	    tickInterval = null;
116	}
117	
118	function isActivePhase(phase: OracleCommandPhase) {
119	    return phase === 'submitted' || phase === 'deliberating' || phase === 'stale';
120	}
121	
122	function getElapsedMs(submittedAt: number | null, fallback = 0) {
123	    return submittedAt ? Math.max(0, Date.now() - submittedAt) : fallback;
124	}
125	
126	function startElapsedClock(requestId: string) {
127	    clearIntervalSafe(tickInterval);
128	    tickInterval = globalThis.setInterval(() => {
129	        setState((current) => {
130	            if (current.requestId !== requestId || !current.submittedAt || !isActivePhase(current.phase)) {
131	                clearIntervalSafe(tickInterval);
132	                tickInterval = null;
133	                return current;
134	            }
135	            return {
136	                ...current,
137	                elapsedMs: getElapsedMs(current.submittedAt, current.elapsedMs)
138	            };
139	        });
140	    }, 250);
141	}
142	
143	function schedulePhaseTimers(requestId: string) {
144	    phaseTimer = globalThis.setTimeout(() => {
145	        setState((current) => {
146	            if (current.requestId !== requestId || current.phase !== 'submitted') {
147	                return current;
148	            }
149	            return {
150	                ...current,
151	                phase: 'deliberating',
152	                elapsedMs: getElapsedMs(current.submittedAt, current.elapsedMs)
153	            };
154	        });
155	    }, ORACLE_COMMAND_BUDGETS_MS.deliberationDelay);
156	
157	    staleSoftTimer = globalThis.setTimeout(() => {
158	        setState((current) => {
159	            if (current.requestId !== requestId || !isActivePhase(current.phase)) {
160	                return current;
161	            }
162	            return {
163	                ...current,
164	                phase: 'stale',
165	                staleLevel: 'soft',
166	                elapsedMs: getElapsedMs(current.submittedAt, current.elapsedMs)
167	            };
168	        });
169	    }, ORACLE_COMMAND_BUDGETS_MS.staleSoft);
170	
171	    staleHardTimer = globalThis.setTimeout(() => {
172	        setState((current) => {
173	            if (current.requestId !== requestId || !isActivePhase(current.phase)) {
174	                return current;
175	            }
176	            return {
177	                ...current,
178	                phase: 'stale',
179	                staleLevel: 'hard',
180	                elapsedMs: getElapsedMs(current.submittedAt, current.elapsedMs)
181	            };
182	        });
183	    }, ORACLE_COMMAND_BUDGETS_MS.staleHard);
184	}
185	
186	function hardTimeoutForMode(mode: OracleCommandMode) {
187	    return mode === 'council'
188	        ? ORACLE_COMMAND_BUDGETS_MS.councilHardTimeout
189	        : ORACLE_COMMAND_BUDGETS_MS.directHardTimeout;
190	}
191	
192	function makeRequestId() {
193	    requestCounter += 1;
194	    return `oracle_${Date.now()}_${requestCounter}`;
195	}
196	
197	function normalizeError(error: unknown) {
198	    if (error instanceof Error) {
199	        return error.message || 'ORACLE_COMMAND_FAILED';
200	    }
201	    if (typeof error === 'string' && error.trim()) {
202	        return error.trim();
203	    }
204	    return 'ORACLE_COMMAND_FAILED';
205	}
206	
207	function settleRequest(requestId: string, phase: 'completed' | 'failed', patch: Partial<OracleCommandState>) {
208	    stopTimers();
209	    setState((current) => {
210	        if (current.requestId !== requestId) return current;
211	        const settledAt = Date.now();
212	        return {
213	            ...current,
214	            ...patch,
215	            phase,
216	            settledAt,
217	            elapsedMs: getElapsedMs(current.submittedAt, current.elapsedMs)
218	        };
219	    });
220	}
221	
222	export function getOracleCommandState() {
223	    return cloneState(state);
224	}
225	
226	export function subscribeOracleCommandState(listener: OracleCommandListener) {
227	    listeners.add(listener);
228	    listener(getOracleCommandState());
229	    return () => {
230	        listeners.delete(listener);
231	    };
232	}
233	
234	export function resetOracleCommandState() {
235	    stopTimers();
236	    activeController?.abort();
237	    activeController = null;
238	    setState(createIdleState());
239	}
