26	function normalizePath(pathOrUrl: string) {
27	    try {
28	        const parsed = new URL(pathOrUrl, buildOrigin(HTTP_PROTOCOL, PRIMARY_PORT));
29	        return `${parsed.pathname}${parsed.search}`;
30	    } catch {
31	        return pathOrUrl.startsWith('/') ? pathOrUrl : `/${pathOrUrl}`;
32	    }
33	}
34	
35	function dedupe(values: string[]) {
36	    return [...new Set(values.filter(Boolean))];
37	}
38	
39	function parsePortList(value?: string) {
40	    return (value || '')
41	        .split(',')
42	        .map((port) => port.trim())
43	        .filter(Boolean);
44	}
45	
46	const FALLBACK_PORTS = dedupe([
47	    ...parsePortList(runtimeEnv.VITE_API_FALLBACK_PORTS),
48	    runtimeEnv.VITE_API_FALLBACK_PORT?.trim() || '',
49	    '3005',
50	    '3003'
51	]);
