53	export const API_ORIGINS = dedupe([
54	    CONFIGURED_API_ORIGIN || buildOrigin(HTTP_PROTOCOL, PRIMARY_PORT),
55	    ...(CONFIGURED_API_ORIGIN ? [] : FALLBACK_PORTS.map((port) => buildOrigin(HTTP_PROTOCOL, port)))
56	]);
