87	function extractBootstrapToken(response: Response, payload: unknown) {
88	    const headerToken = response.headers.get(AUTH_HEADER_NAME) || response.headers.get(AUTH_HEADER_NAME.toLowerCase());
89	    if (headerToken?.trim()) return headerToken.trim();
90	
91	    if (typeof payload === 'string') {
92	        const trimmed = payload.trim();
93	        return trimmed || null;
94	    }
95	
96	    if (!payload || typeof payload !== 'object') return null;
97	
98	    const candidate = (payload as Record<string, unknown>).apiKey
99	        || (payload as Record<string, unknown>).api_key
100	        || (payload as Record<string, unknown>).token
101	        || (payload as Record<string, unknown>).authToken
102	        || (payload as Record<string, unknown>).value
103	        || (payload as Record<string, unknown>).key;
104	
105	    return typeof candidate === 'string' && candidate.trim() ? candidate.trim() : null;
106	}
