199	export async function apiFetchWithTimeout(pathOrUrl: string, timeoutMs: number, init: RequestInit = {}) {
200	    const controller = new AbortController();
201	    const upstreamSignal = init.signal;
202	    let timedOut = false;
203	
204	    const onUpstreamAbort = () => controller.abort();
205	    if (upstreamSignal) {
206	        if (upstreamSignal.aborted) {
207	            onUpstreamAbort();
208	        } else {
209	            upstreamSignal.addEventListener('abort', onUpstreamAbort, { once: true });
210	        }
211	    }
212	
213	    const timeoutId = globalThis.setTimeout(() => {
214	        timedOut = true;
215	        controller.abort();
216	    }, timeoutMs);
217	
218	    try {
219	        return await apiFetch(pathOrUrl, { ...init, signal: controller.signal });
220	    } catch (error: any) {
221	        if (timedOut && error?.name === 'AbortError') {
222	            const timeoutError = new Error(`REQUEST_TIMEOUT_${timeoutMs}MS`);
223	            timeoutError.name = 'AbortError';
224	            throw timeoutError;
225	        }
226	        throw error;
227	    } finally {
228	        globalThis.clearTimeout(timeoutId);
229	        if (upstreamSignal) {
230	            upstreamSignal.removeEventListener('abort', onUpstreamAbort);
231	        }
232	    }
233	}
