107	function redactSecrets(content: string): string {
108	    let redacted = content;
109	    const patterns = [
110	        /sk-[a-zA-Z0-9]{32,}/g,           // OpenAI / Generic Secret Keys
111	        /xkeysia-[a-zA-Z0-9]{60,}/g,      // Anthropic / Sendinblue
112	        /AIza[0-9A-Za-z-_]{35}/g,         // Google Cloud API Keys
113	        /ghp_[a-zA-Z0-9]{36}/g,           // GitHub PAT
114	        /ey[a-zA-Z0-9-_]{20,}\.ey[a-zA-Z0-9-_]{20,}\.[a-zA-Z0-9-_]{20,}/g, // JWTs
115	        /password\s*[:=]\s*["']?[^"'\s,]+["']?/gi, // Potential passwords
116	    ];
117	
118	    for (const pattern of patterns) {
119	        redacted = redacted.replace(pattern, (match) => {
120	            const prefix = match.substring(0, 4);
121	            return `${prefix}...[REDACTED_BY_GUARDIAN]`;
122	        });
123	    }
124	    return redacted;
125	}
